<?php /* VIVA NOTE: Nearby-facility declarations; an Agent must independently verify them. */ ?><div class="toolbar"><p>Surrounding facilities near <strong><?=e($property['title'])?></strong>. Field Agents separately verify each claim.</p><a href="<?=e(url('/property/show',['id'=>$property['property_id']]))?>">← Back</a></div>
<div class="two-panel"><section class="panel"><h3>Existing facilities</h3><?php if(!$facilities):?><div class="empty">No facilities added yet.</div><?php endif;?>
<?php foreach($facilities as $f):?><article class="item-line"><div><strong><?=e($f['facility_name'])?></strong><small><?=e(pill($f['facility_type']))?> · <?=e($f['distance_meters']??'—')?> m</small><span class="status"><?=e(pill($f['verification_status']))?></span></div>
<?php if($f['verification_status']==='pending'):?><form method="post" action="<?=e(url('/property/facilities/remove',['id'=>$property['property_id']]))?>" data-confirm="Remove this unverified facility?"><?=csrf_field()?><input type="hidden" name="facility_id" value="<?=e($f['facility_id'])?>"><button class="btn small danger">Remove</button></form><?php endif;?></article><?php endforeach;?></section>
<section class="panel"><h3>Add facility</h3><form method="post" action="<?=e(url('/property/facilities/add',['id'=>$property['property_id']]))?>" class="stack"><?=csrf_field()?>
<label>Category<select name="type"><?php foreach(['bus_route','supermarket','grocery','pharmacy','hospital','railway_station','restaurant','other'] as $f):?><option value="<?=e($f)?>"><?=e(pill($f))?></option><?php endforeach;?></select></label>
<label>Name<input name="name" required maxlength="150" placeholder="Bus route 138, supermarket..." ></label><label>Distance in metres<input type="number" name="distance" min="0" max="100000"></label><label>Details<input name="details" maxlength="255"></label><button class="btn">Add for inspection</button></form></section></div>
